import vail as hl
def test_upstream_show_various_types():
    ht = hl.utils.range_table(1)
    ht = ht.annotate(x1=[1], x2=[hl.struct(y=[1])], x3={1}, x4={1: 'foo'}, x5={hl.struct(foo=5): 'bar'}, x6=hl.tuple(()), x7=hl.tuple(('3',)), x8=hl.tuple(('3', 3)), x9=4.2, x10=hl.dict({'hello': 3, 'bar': 5}), x11=(True, False))
    result = ht.show(handler=str)
    assert result == '+-------+--------------+--------------------------------+------------+\n|   idx | x1           | x2                             | x3         |\n+-------+--------------+--------------------------------+------------+\n| int32 | array<int32> | array<struct{y: array<int32>}> | set<int32> |\n+-------+--------------+--------------------------------+------------+\n|     0 | [1]          | [([1])]                        | {1}        |\n+-------+--------------+--------------------------------+------------+\n\n+------------------+-------------------------------+---------+------------+\n| x4               | x5                            | x6      | x7         |\n+------------------+-------------------------------+---------+------------+\n| dict<int32, str> | dict<struct{foo: int32}, str> | tuple() | tuple(str) |\n+------------------+-------------------------------+---------+------------+\n| {1:"foo"}        | {(5):"bar"}                   | ()      | ("3")      |\n+------------------+-------------------------------+---------+------------+\n\n+-------------------+----------+---------------------+-------------------+\n| x8                |       x9 | x10                 | x11               |\n+-------------------+----------+---------------------+-------------------+\n| tuple(str, int32) |  float64 | dict<str, int32>    | tuple(bool, bool) |\n+-------------------+----------+---------------------+-------------------+\n| ("3",3)           | 4.20e+00 | {"bar":5,"hello":3} | (True,False)      |\n+-------------------+----------+---------------------+-------------------+\n'
